powershell -NoProfile -Command "$ws=New-Object -ComObject WScript.Shell; $roots=@(($env:APPDATA + '\Microsoft\Windows\Start Menu\Programs\Chrome Apps'),($env:APPDATA + '\Microsoft\Windows\Start Menu\Programs\Edge Apps')); $src=Get-ChildItem -Path $roots -Filter 'Hilo.lnk' -ErrorAction SilentlyContinue | Select-Object -First 1; if(-not $src){ Write-Host 'Hilo PWA shortcut not found. Install it first: open https://__HILO_BASE_URL__ in Chrome or Edge and choose Install (the install icon at the right of the address bar), then re-run this command.' -ForegroundColor Yellow; return }; $lnk=$ws.CreateShortcut($src.FullName); $dst=Join-Path ([Environment]::GetFolderPath('Startup')) 'Hilo.lnk'; $new=$ws.CreateShortcut($dst); $new.TargetPath=$lnk.TargetPath; $new.Arguments=$lnk.Arguments; $new.WorkingDirectory=$lnk.WorkingDirectory; $new.IconLocation=$lnk.IconLocation; $new.WindowStyle=7; $new.Description='Hilo (launch minimized at login)'; $new.Save(); Write-Host ('Done. Startup shortcut created from ' + $src.FullName + ' -> ' + $dst) -ForegroundColor Green"